pub struct RuleState {
    /// Range of the offending selector.
    range: TextRange,
    /// Number of class selectors found in the selector.
    found: usize,
}

impl Rule for NoExcessiveSelectorClasses {
    type Query = Ast<AnyCssSelectorRule>;
    type State = RuleState;
    type Signals = Box<[Self::State]>;
    type Options = NoExcessiveSelectorClassesOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let Some(max_classes) = ctx.options().max_classes else {
            return Box::new([]);
        };
        let max_classes = max_classes as usize;

        let selectors: Vec<CssSyntaxNode> = match ctx.query() {
            AnyCssSelectorRule::CssQualifiedRule(rule) => {
                rule.prelude().into_iter().map(|s| s.into_syntax()).collect()
            }
            AnyCssSelectorRule::CssNestedQualifiedRule(rule) => {
                rule.prelude().into_iter().map(|s| s.into_syntax()).collect()
            }
        };

        let mut signals = Vec::new();
        for selector in selectors {
            // SCSS selectors with interpolation are dynamic and cannot be
            // reliably analyzed, so we skip them.
            if contains_interpolation(&selector) {
                continue;
            }

            let found = count_class_selectors(&selector);
            if found > max_classes {
                signals.push(RuleState {
                    range: selector.text_trimmed_range(),
                    found,
                });
            }
        }

        signals.into_boxed_slice()
    }

    fn diagnostic(ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let max_classes = ctx.options().max_classes? as usize;
        let found = state.found;

        let message = if max_classes == 1 {
            markup! {
                "Expected this selector to have no more than "{max_classes}" class selector, but found "{found}"."
            }
            .to_owned()
        } else {
            markup! {
                "Expected this selector to have no more than "{max_classes}" class selectors, but found "{found}"."
            }
            .to_owned()
        };

        Some(
            RuleDiagnostic::new(rule_category!(), state.range, message)
                .note(markup! {
                    "Selectors with too many chained classes are harder to read, override, and reuse."
                })
                .note(markup! {
                    "Reduce the number of class selectors in this selector, or split it into simpler selectors."
                }),
        )
    }
}

/// Counts every class selector within `selector`, including those appearing
/// inside functional pseudo-class arguments (e.g. `:not()`, `:is()`, `:has()`).
fn count_class_selectors(selector: &CssSyntaxNode) -> usize {
    selector
        .descendants()
        .filter(|node| node.kind() == CssSyntaxKind::CSS_CLASS_SELECTOR)
        .count()
}

/// Returns `true` if `selector` contains an SCSS interpolation such as
/// `#{$variable}`.
fn contains_interpolation(selector: &CssSyntaxNode) -> bool {
    selector
        .descendants()
        .any(|node| node.kind() == CssSyntaxKind::SCSS_INTERPOLATION)
}
